<?php declare(strict_types=1);
require __DIR__.'/../src/bootstrap.php';require __DIR__.'/../src/People/Members/MemberImport.php';require __DIR__.'/../src/People/Members/MemberImportReader.php';
use Kulturhus\Verein\{Database,Registry,MemberImport,MemberImportReader};
set_error_handler(static function($s,$m,$f,$l){if(!(error_reporting()&$s))return false;throw new ErrorException($m,0,$s,$f,$l);});
function ok(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);echo "PASS $m\n";}function denied(callable $f,string $m):void{try{$f();}catch(DomainException){ok(true,$m);return;}throw new RuntimeException($m);}
$db=\Kulturhus\Verein\Tests\MySqlFixture::connect(':memory:');Database::migrate($db);$db->exec("INSERT INTO clubs VALUES('a','A');INSERT INTO actors(id,club_id,role,is_superuser) VALUES('admin','a','members',1),('member','a','member',0)");$r=new Registry($db,'admin');$service=new MemberImport($db,'admin');
$book=MemberImportReader::read('test.csv',"Name;Nr;Eintritt;Austritt;Email;Status\nAnna Test;001;2015;;family@example.invalid;aktiv\nBerta Test;002;2016-02-03;2025-12-31;family@example.invalid;ehemalig\n");$map=['name'=>'0','number'=>'1','start'=>'2','end'=>'3','email'=>'4','status'=>'5'];$p=$service->preview($book,0,1,$map);ok(array_column($p['rows'],'state')===['new','new'],'CSV preview keeps shared email as separate people');ok($p['rows'][0]['record']['start_precision']==='year','year precision recognized');$ids=$service->apply($book,0,1,$map,'',$p['hash']);ok(count($ids)===2,'members imported');ok($r->memberships($ids[0])[0]['member_number']==='001','leading zero number retained');ok($r->memberships($ids[1])[0]['status']==='ehemalig','former membership retained');
$again=$service->preview($book,0,1,$map);ok(array_column($again['rows'],'state')===['existing','existing'],'repeated import skips existing members');ok($service->apply($book,0,1,$map,'',$again['hash'])===[],'repeat creates no duplicates');
$contact=$r->saveContact(null,0,'person','Clara Test','old@example.invalid','Original address');$convert=MemberImportReader::read('c.csv',"Name;Nr;Eintritt\nClara Test;003;2020\n");$p=$service->preview($convert,0,1,$map);ok($p['rows'][0]['state']==='convert','existing contact can become member');$service->apply($convert,0,1,$map,'',$p['hash']);ok($r->contact($contact)['address']==='Original address','conversion preserves contact data');
$collision=MemberImportReader::read('c.csv',"Name;Nr;Eintritt\nDifferent Person;001;2020\n");$p=$service->preview($collision,0,1,$map);ok($p['rows'][0]['state']==='review','number belonging to other name blocked');denied(fn()=>$service->apply($collision,0,1,$map,'',$p['hash']),'unclear rows cannot import');
$fresh=MemberImportReader::read('n.csv',"Name;Nr;Eintritt\nDana Test;004;2020\n");$p=$service->preview($fresh,0,1,$map);$r->saveContact(null,0,'person','Additional contact','','');denied(fn()=>$service->apply($fresh,0,1,$map,'',$p['hash']),'changed database invalidates preview');denied(fn()=>(new MemberImport($db,'member'))->preview($fresh,0,1,$map),'member cannot preview private directory');
$file=tempnam(sys_get_temp_dir(),'xlsx-fixture-');$z=new ZipArchive();$z->open($file,ZipArchive::OVERWRITE);$z->addFromString('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><workbookPr date1904="0"/><sheets><sheet name="Mitglieder" sheetId="1" r:id="rId1"/></sheets></workbook>');$z->addFromString('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Target="worksheets/sheet1.xml"/></Relationships>');$z->addFromString('xl/worksheets/sheet1.xml','<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData><row r="1"><c r="A1" t="inlineStr"><is><t>Name</t></is></c></row><row r="2"><c r="A2" t="inlineStr"><is><t>Excel Test</t></is></c><c r="B2"><f>1+2</f><v>3</v></c></row></sheetData></worksheet>');$z->close();$xlsx=MemberImportReader::read('test.xlsx',file_get_contents($file));unlink($file);ok($xlsx['sheets'][0]['rows'][1][0]==='Excel Test','XLSX inline string read');$p=$service->preview($xlsx,0,1,['name'=>'0','number'=>'1'],'2020-01-01');ok($p['rows'][0]['state']==='review','mapped formula blocks import');
ok(\Kulturhus\Verein\Tests\MySqlFixture::integrity($db)==='ok','database remains consistent');
